scwin.vCurrPageNo = 0; //현재 선택된 페이지번호
scwin.gSrchYn = 'N'; // 최초오픈여부

scwin.vScrenID = 'ULDSTF15600.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_sessionCheck = function() {
    scwin.gUsrId = js_id;
    if (scwin.gUsrId == "" || scwin.gUsrId.length == 0) {
        $c.win.alert("로그인 페이지로 이동합니다.");
        this.location.href = "/menu/login.jsp";

    }
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    //gEmpNo =  js_emp_no;
    scwin.gLdMktTp = js_market;
    scwin.gLdMktTp = js_market;
    // 유가 및 코스닥 종목을 동시에 보는 화면이므로 추가함.
    if (scwin.gLdMktTp == '1') {
        $c.stf.setObjectValue(rdo_MKT_ID, '9'); // 유가일때는 디폴트로  전체 셋팅

    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    }

    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !기초자산공시--;
목록검색;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    var vRsnList = "";
    var vCnt = 0;
    if (chb_001.checked == true) {
        vRsnList = '001';
        vCnt++;
    }
    if (chb_016.checked == true) {
        if (vCnt > 0) {
            vRsnList += ',016';
        } else {
            vRsnList = '016';
        }
        vCnt++;
    }
    if (chb_023.checked == true) {
        if (vCnt > 0) {
            vRsnList += ',023';
        } else {
            vRsnList = '023';
        }
        vCnt++;
    }
    if (chb_029.checked == true) {
        if (vCnt > 0) {
            vRsnList += ',029';
        } else {
            vRsnList = '029';
        }
        vCnt++;
    }
    if (chb_038.checked == true) {
