        }
        vCnt++;
    }
    if (chb_027.checked == true) {
        if (vCnt > 0) {
            vRsnList += ',027';
        } else {
            vRsnList = '027';
        }
        vCnt++;
    }
    if (chb_031.checked == true) {
        if (vCnt > 0) {
            vRsnList += ',031';
        } else {
            vRsnList = '031';
        }
        vCnt++;
    }
    if (chb_013.checked == true) {
        if (vCnt > 0) {
            vRsnList += ',013';
        } else {
            vRsnList = '013';
        }
        vCnt++;
    }

    //elw 공시사유분류 검색조건추가  start 2011.01.06
    if (chb_009.checked == true) {
        if (vCnt > 0) {
            vRsnList += ',009';
        } else {
            vRsnList = '009';
        }
        vCnt++;
    }
    if (chb_064.checked == true) {
        if (vCnt > 0) {
            vRsnList += ',064';
        } else {
            vRsnList = '064';
        }
        vCnt++;
    }

    //elw 공시사유분류 검색조건추가 end


    // 예외적으로 사유가 아닌 서식코드임	
    if (chb_70764.checked == true) {
        scwin.gRsn70764YN = 'Y';
        vCnt++;
    } else {
        scwin.gRsn70764YN = 'N';
    }

    //elw 공시사유분류 검색조건추가  start 2011.01.06
    if (chb_11200.checked == true) {
        scwin.gRsn11200YN = 'Y';
        vCnt++;
    } else {
        scwin.gRsn11200YN = 'N';
    }
    //elw 공시사유분류 검색조건추가 end

    //매매거래정지항목 추가 2012.02.28
    if (chb_TrHaltYn.checked == true) {
        scwin.gRsnTrHaltYN = 'Y';
        vCnt++;
    } else {
        scwin.gRsnTrHaltYN = 'N';
    }
    if (chb_outside.checked == true) {
        scwin.gRsnExceptYN = 'Y';
        vCnt++;
    } else {
        scwin.gRsnExceptYN = 'N';
    }
    if (vCnt <= 0 && $c.stf.getObjectValue(txb_FormNm) == '') {
        $c.win.alert('한개이상 공시사유를 체크하시거나  공시제목을 입력하시기 바랍니다.');
        return false;
    }

    // 맨뒤에 ", " 제거 하기 
    scwin.gRsnList = vRsnList;

    //alert(gDocList);
    scwin.gSrchYn = 'Y'; // 검색했으면 Y로 셋팅
    fn_Search();
} < !기초자산공시--;
엑셀다운로드-- > function() {
    var url = "/DisclosureSearch.do?method=listUlyDiscls&inputMessageId=ULYDSCLCOND_IN" + "&outputMessageId=ULYDSCLLIST_OUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + js_belngdepcd + "&EMP_NO=" + scwin.gEmpNo + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&RSN_CLSS_CD_LIST=" + scwin.gRsnList + "&RSN_70764=" + scwin.gRsn70764YN + "&RSN_11200=" + scwin.gRsn11200YN + "&RSN_TRHALT_YN=" + scwin.gRsnTrHaltYN + "&RSN_EXCEPT=" + scwin.gRsnExceptYN + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_07;
    dts_DsclList_excel.DataID = encodeURI(url);
    dts_DsclList_excel.reset();
} < !기초자산공시--;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    dts_DsclList_excel.removeAll();
    var edt_FromDate_year = $c.stf.getObjectValue(edt_FromDate).substr(0, 4);
    var edt_FromDate_month = $c.stf.getObjectValue(edt_FromDate).substr(4, 2) - 1;
    var edt_FromDate_day = $c.stf.getObjectValue(edt_FromDate).substr(6, 2);
    var edt_FromDate_Date = new Date(edt_FromDate_year, edt_FromDate_month, edt_FromDate_day);
    var edt_ToDate_year = $c.stf.getObjectValue(edt_ToDate).substr(0, 4);
    var edt_ToDate_month = $c.stf.getObjectValue(edt_ToDate).substr(4, 2) - 1;
    var edt_ToDate_day = $c.stf.getObjectValue(edt_ToDate).substr(6, 2);
    var edt_ToDate_Date = new Date(edt_ToDate_year, edt_ToDate_month, edt_ToDate_day);

    // 5년 이상의 기간은 검색 할 수 없다
    var date_result = (Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date)) / (1000 * 60 * 60 * 24);
    if (date_result > 1826) {
        $c.win.alert("검색기간은 5년 이상을 초과 할 수 없습니다.");
        return;
    }
    var url = "/DisclosureSearch.do?method=pagingUlyDiscls&inputMessageId=ULYDSCLCOND_IN" + "&outputMessageId=ULYDSCLLIST_OUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + js_belngdepcd + "&EMP_NO=" + scwin.gEmpNo + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&RSN_CLSS_CD_LIST=" + scwin.gRsnList + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&RSN_70764=" + scwin.gRsn70764YN + "&RSN_11200=" + scwin.gRsn11200YN + "&RSN_TRHALT_YN=" + scwin.gRsnTrHaltYN + "&RSN_EXCEPT=" + scwin.gRsnExceptYN + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.PageNoCall = function(vPageNo) {
    //현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    var url = "/DisclosureSearch.do?method=pagingUlyDiscls&inputMessageId=ULYDSCLCOND_IN" + "&outputMessageId=ULYDSCLLIST_OUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + js_belngdepcd + "&EMP_NO=" + scwin.gEmpNo + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&RSN_CLSS_CD_LIST=" + scwin.gRsnList + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&RSN_70764=" + scwin.gRsn70764YN + "&RSN_11200=" + scwin.gRsn11200YN + "&RSN_TRHALT_YN=" + scwin.gRsnTrHaltYN + "&RSN_EXCEPT=" + scwin.gRsnExceptYN + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
    $c.cm.ShowWin(grd_Grid);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclList.getCellData(eval(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclList.getCellData(eval(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclList.getCellData(eval(obj), "ISUR_CD");

    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
